+package org.apache.streampipes.rest.shared.util;
+
+import java.net.InetAddress;
+import java.net.URL;
+import java.util.Arrays;
+import java.util.HashSet;
+import java.util.Set;
+
+/**
+ * Utility class for validating URLs to prevent SSRF vulnerabilities.
+ */
+public class UrlValidator {
+
+  private static final Set<String> ALLOWED_SCHEMES = new HashSet<>(Arrays.asList("http", "https"));
+
+  /**
+   * Validates a URL to ensure it is safe for server-side requests.
+   * @param urlString the URL string to validate
+   * @return true if the URL is valid and safe, false otherwise
+   */
+  public static boolean isValidUrl(String urlString) {
+    if (urlString == null || urlString.isEmpty()) {
+      return false;
+    }
+
+    try {
+      URL url = new URL(urlString);
+
+      // Only allow http and https schemes
+      if (!ALLOWED_SCHEMES.contains(url.getProtocol().toLowerCase())) {
+        return false;
+      }
+
+      String host = url.getHost();
+      if (host == null || host.isEmpty()) {
+        return false;
+      }
+
+      // Resolve the host and check if it points to a private/reserved address
+      InetAddress address = InetAddress.getByName(host);
+      if (isPrivateOrReservedAddress(address)) {
+        return false;
+      }
+
+      return true;
+    } catch (Exception e) {
+      return false;
+    }
+  }
+
+  private static boolean isPrivateOrReservedAddress(InetAddress address) {
+    // Check for loopback address
+    if (address.isLoopbackAddress()) {
+      return true;
+    }
+
+    // Check for private site-local address (10.x.x.x, 172.16-31.x.x, 192.168.x.x)
+    if (address.isSiteLocalAddress()) {
+      return true;
+    }
+
+    // Check for link-local address (169.254.x.x)
+    if (address.isLinkLocalAddress()) {
+      return true;
+    }
+
+    return false;
+  }
+}

