+    
+    // Security: Test that oversized modules are rejected
+    func testModuleSizeLimit() {
+        var data = Data([0x00, 0x61, 0x73, 0x6D, 0x01, 0x00, 0x00, 0x00]) // magic + version
+        // Add oversized section
+        data.append(SectionCode.type.rawValue)
+        data.append(contentsOf: [0xFF, 0xFF, 0xFF, 0xFF, 0x0F]) // LEB128 max
+        
+        let parser = Parser(data: data)
+        XCTAssertThrowsError(try parser.parseModule()) { error in
+            XCTAssertTrue(error is ParseError)
+        }
+    }
+    
+    // Security: Test that excessive function counts are rejected
+    func testFunctionCountLimit() {
+        var data = Data([0x00, 0x61, 0x73, 0x6D, 0x01, 0x00, 0x00, 0x00])
+        data.append(SectionCode.function.rawValue)
+        data.append(0x0A) // section size
+        data.append(contentsOf: [0xFF, 0xFF, 0xFF, 0xFF, 0x0F]) // count = max uint32
+        
+        let parser = Parser(data: data)
+        XCTAssertThrowsError(try parser.parseModule()) { error in
+            guard let parseError = error as? ParseError else {
+                XCTFail("Expected ParseError")
+                return
+            }
+            if case .tooManyFunctions = parseError {
+                // Expected
+            } else {
+                XCTFail("Expected tooManyFunctions error")
+            }
+        }
+    }
+    
+    // Security: Test that valid small modules still parse correctly
